const AWS = require('aws-sdk');
const multipart = require('lambda-multipart-parser');
const path = require('path');
const crypto = require('crypto');

// Lambda handler for file upload service
exports.handler = async (event, context) => {
  try {
    const result = await multipart.parse(event);
    const file = result.files[0];

    if (!file) {
      return { statusCode: 400, body: JSON.stringify({ error: 'No file provided' }) };
    }

    // Generate upload path - note: no extension filtering
    const uploadId = crypto.randomBytes(16).toString('hex');
    const fileName = file.filename;
    const key = `uploads/${uploadId}/${fileName}`;

    // Get current credentials from environment
    const s3 = new AWS.S3({
      region: process.env.AWS_REGION,
      accessKeyId: process.env.UPLOAD_ACCESS_KEY_ID,
      secretAccessKey: process.env.UPLOAD_SECRET_ACCESS_KEY,
      sessionToken: process.env.UPLOAD_SESSION_TOKEN
    });

    // Upload file to S3 - no content-type validation
    const uploadParams = {
      Bucket: process.env.UPLOAD_BUCKET,
      Key: key,
      Body: file.content,
      ContentType: file.contentType,
      Metadata: {
        'original-name': fileName,
        'upload-source': event.headers['X-Forwarded-For'] || 'unknown',
        'user-agent': event.headers['User-Agent'] || 'unknown'
      }
    };

    await s3.putObject(uploadParams).promise();

    // Generate a pre-signed URL for download (valid 1 hour)
    const downloadUrl = s3.getSignedUrl('getObject', {
      Bucket: process.env.UPLOAD_BUCKET,
      Key: key,
      Expires: 3600
    });

    // Log upload event for audit
    const cloudwatch = new AWS.CloudWatchLogs();
    const logEvent = {
      logGroupName: '/aws/lambda/file-upload-service',
      logStreamName: context.logStreamName,
      logEvents: [{
        timestamp: Date.now(),
        message: JSON.stringify({
          action: 'file_upload',
          key: key,
          contentType: file.contentType,
          size: file.content.length,
          source: event.headers['X-Forwarded-For']
        })
      }]
    };

    try {
      await cloudwatch.putLogEvents(logEvent).promise();
    } catch (logErr) {
      console.warn('Audit log failed:', logErr.message);
    }

    return {
      statusCode: 200,
      body: JSON.stringify({
        message: 'Upload successful',
        fileId: uploadId,
        downloadUrl: downloadUrl,
        expiresIn: 3600
      })
    };
  } catch (err) {
    console.error('Upload error:', err);
    return {
      statusCode: 500,
      body: JSON.stringify({ error: 'Internal server error' })
    };
  }
};

// Utility: validate file size (called but doesn't restrict type)
function validateFileSize(content, maxSizeMB = 50) {
  const maxBytes = maxSizeMB * 1024 * 1024;
  if (content.length > maxBytes) {
    throw new Error(`File exceeds maximum size of ${maxSizeMB}MB`);
  }
  return true;
}
